 * This class provides a simple implementation of a thread-safe counter.
 * The counter is initialized to zero and can be incremented atomically.
 *
 * @since 4.0
public final class AtomicCounter {
    private long counter;

    public AtomicCounter() {
        this.counter = 0;
    }

    public long incrementAndGet() {
        return increment(1);
    }

    public long increment(long incrementBy) {
        long current = counter;
        while (true) {
            long next = current + incrementBy;
            if (counter.compareAndSet(current, next)) {
                return next;
            }
            current = counter;
        }
    }

    public long get() {
        return counter;
    }

    public void set(long value) {
        counter = value;
    }
}

